// hive-managed: session events
// Generated by Hive; `hive update` rewrites this file and `hive plan remove` deletes it.
// It reports Pi session events to the Hive viewer by running
// `hive hook pi <event>` detached, so Pi never waits for it and the hook cannot
// print into the session. The session ID is Pi's own, passed explicitly.
// @ts-nocheck

import { spawn } from "node:child_process";

const EXECUTABLE = __HIVE_EXECUTABLE__;

function report(name: string, event: any, ctx: any): void {
  try {
    const sessionId = ctx?.sessionManager?.getSessionId?.();
    if (typeof sessionId !== "string" || sessionId === "") return;
    const stamp = typeof event?.timestamp === "number" && Number.isFinite(event.timestamp) ? event.timestamp : Date.now();
    const body = JSON.stringify({
      session_id: sessionId,
      cwd: typeof ctx?.cwd === "string" ? ctx.cwd : "",
      occurred_at: new Date(stamp).toISOString(),
    });
    const child = spawn(EXECUTABLE, ["hook", "pi", name], {
      stdio: ["pipe", "ignore", "ignore"],
      detached: true,
      windowsHide: true,
    });
    child.on("error", () => {});
    child.stdin.on("error", () => {});
    child.stdin.end(body);
    child.unref();
  } catch {
    // A hook must never disturb the host.
  }
}

export default function (pi: any) {
  pi.on("session_start", (event: any, ctx: any) => report("session_start", event, ctx));
  pi.on("agent_settled", (event: any, ctx: any) => report("agent_settled", event, ctx));
  pi.on("session_shutdown", (event: any, ctx: any) => report("session_shutdown", event, ctx));
}
